import org.springframework.batch.core.*;
import org.springframework.batch.core.configuration.annotation.EnableBatchProcessing;
import org.springframework.batch.core.job.builder.JobBuilder;
import org.springframework.batch.core.step.builder.StepBuilder;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
@EnableBatchProcessing
public class BatchConfig {
  // ✅ NEW: chunk of 500 — each chunk commits as one transaction.
  @Bean
  Step importStep(JobRepository repo, PlatformTransactionManager tm,
      ItemReader<Row> reader, ItemProcessor<Row, Out> processor, ItemWriter<Out> writer) {
    return new StepBuilder("import", repo)
        .<Row, Out>chunk(500, tm) // ✅ NEW: atomic per-chunk commit
        .reader(reader)
        .processor(processor)
        .writer(writer)
        .faultTolerant()
        .skip(Exception.class).skipLimit(50) // ✅ NEW: skip bad records
        .retry(TransientException.class).retryLimit(3) // ✅ NEW: retry
        .build();
  }

  @Bean
  Job importJob(JobRepository repo, Step importStep) {
    return new JobBuilder("import", repo)
        .start(importStep)
        .build();
  }
}

// ✅ NEW: JobRepository persists state — a crash restarts from the
// last committed chunk instead of redoing everything.
